(3015402, 424027, 59633, '<td valign="top">This is a very good picture!! Good shot, great lights</td>', 'This is a very good picture!! Good shot, great lights', '2006-11-08 17:02:00.000000', NULL, 1),
(3015416, 423291, 60173, '<td valign="top">I think this shot would have been much better without the car that looks like it''s going to crash into the building. One great thing about that place is the amount of people that are usually gathered around. Without that blurry car in the way I think you would have been able to capture the people aspect better. Great colors. There''s another Geno''s entry where the colors didn''t seem right to me. After seeing yours my suspicions were right.</td>', 'I think this shot would have been much better without the car that looks like it''s going to crash into the building. One great thing about that place is the amount of people that are usually gathered around. Without that blurry car in the way I think you would have been able to capture the people aspect better. Great colors. There''s another Geno''s entry where the colors didn''t seem right to me. After seeing yours my suspicions were right.', '2006-11-08 17:06:36.000000', NULL, 1),
(3015433, 424349, 62095, '<td valign="top">Zzzt. ZZzt.  ZZZt.  I bet that''s the noise this sign makes.  It probably flashes.  People waiting for taxis and buses would probably notice, if they weren''t drunk.</td>', 'Zzzt. ZZzt.  ZZZt.  I bet that''s the noise this sign makes.  It probably flashes.  People waiting for taxis and buses would probably notice, if they weren''t drunk.', '2006-11-08 17:12:00.000000', NULL, 1),
(3015439, 424394, 62095, '<td valign="top">Well quite. There''s an inviting sign.</td>', 'Well quite. There''s an inviting sign.', '2006-11-08 17:12:37.000000', NULL, 1),
(3015440, 423917, 60173, '<td valign="top">It''s like Where''s Waldo.. I found the neon sign! If taken out of the neon sign challenge I think this is a pretty decent clean shot. However it is a neon sign challenge and finding the sign is actually a challenge in itself.</td>', 'It''s like Where''s Waldo.. I found the neon sign! If taken out of the neon sign challenge I think this is a pretty decent clean shot. However it is a neon sign challenge and finding the sign is actually a challenge in itself.', '2006-11-08 17:12:54.000000', NULL, 1),
(3015446, 424098, 62095, '<td valign="top">I''m thinking a martini glass may have worked better, but still good.</td>', 'I''m thinking a martini glass may have worked better, but still good.', '2006-11-08 17:13:58.000000', NULL, 1),
(3015449, 423721, 62095, '<td valign="top">ooer.</td>', 'ooer.', '2006-11-08 17:14:09.000000', NULL, 1),
