(3019343, 422038, 42013, '<td valign="top">Like your title ;)</td>', 'Like your title ;)', '2006-11-10 02:51:49.000000', NULL, 1),
(3019344, 424414, 42013, '<td valign="top">I suspect you will do quite well in this challenge! Certainly creative thinking. HOw would it look with the eyelids desaturated? Not sure if you could do this in basic but maybe???</td>', 'I suspect you will do quite well in this challenge! Certainly creative thinking. HOw would it look with the eyelids desaturated? Not sure if you could do this in basic but maybe???', '2006-11-10 02:54:28.000000', NULL, 1),
(3019569, 424137, 67301, '<td valign="top">I really can''t see a neon sign</td>', 'I really can''t see a neon sign', '2006-11-10 08:03:24.000000', NULL, 1),
(3019681, 421748, 33105, '<td valign="top">Kinda neat...this is about 1 mile from my home!</td>', 'Kinda neat...this is about 1 mile from my home!', '2006-11-10 09:20:03.000000', NULL, 1),
(3019886, 424215, 57121, '<td valign="top">bessst one. i love the water effect. perhaps it was taken througha windshield while raining? i dont know. its a nice guessor. i like it alot. 10</td>', 'bessst one. i love the water effect. perhaps it was taken througha windshield while raining? i dont know. its a nice guessor. i like it alot. 10', '2006-11-10 10:57:37.000000', NULL, 1),
(3019887, 421858, 57121, '<td valign="top">i like the simplicity</td>', 'i like the simplicity', '2006-11-10 10:57:55.000000', NULL, 1),
(3020049, 424105, 54778, '<td valign="top">The choice to make it b/w was a good one.. It definitely works for the pic..</td>', 'The choice to make it b/w was a good one.. It definitely works for the pic..', '2006-11-10 12:05:06.000000', NULL, 1),
(3020055, 424182, 54778, '<td valign="top">Nice perspective and angle</td>', 'Nice perspective and angle', '2006-11-10 12:08:24.000000', NULL, 1),
(3020066, 424414, 52713, '<td valign="top">This is awesome. Please post the details after the challenge</td>', 'This is awesome. Please post the details after the challenge', '2006-11-10 12:14:04.000000', NULL, 1),
(3020238, 423652, 47191, '<td valign="top">GREAT HAND - SMS</td>', 'GREAT HAND - SMS', '2006-11-10 13:34:57.000000', NULL, 1),
(3020248, 424049, 54778, '<td valign="top">Really cool angle</td>', 'Really cool angle', '2006-11-10 13:38:45.000000', NULL, 1),
(3020295, 423312, 63433, '<td valign="top">i like that it is in black and white. the point of a neon sign is to stand out through its bright colors but this is very interesting</td>', 'i like that it is in black and white. the point of a neon sign is to stand out through its bright colors but this is very interesting', '2006-11-10 14:05:38.000000', NULL, 1),
(3020299, 424474, 30049, '<td valign="top">I think your approach to this challenge is unique and I''ve enjoyed it.  Thanks for being "creative".  :D  Good luck in the challenge.</td>', 'I think your approach to this challenge is unique and I''ve enjoyed it.  Thanks for being "creative".  :D  Good luck in the challenge.', '2006-11-10 14:08:53.000000', NULL, 1),
(3020300, 423807, 30049, '<td valign="top">Well, this is just NOT fair!  :D  What a sign to find for this challenge.  Woo-hoo!!!  It''s fun, it''s clear and well focused - simple and not cluttered.  Great find and wonderfully captured.  Best of luck to you in the challenge.</td>', 'Well, this is just NOT fair!  :D  What a sign to find for this challenge.  Woo-hoo!!!  It''s fun, it''s clear and well focused - simple and not cluttered.  Great find and wonderfully captured.  Best of luck to you in the challenge.', '2006-11-10 14:10:18.000000', NULL, 1),
(3020301, 424356, 30049, '<td valign="top">Great job on exposing the light correctly on this.  It''s a very cool find for this challenge.  I''d wish you good luck in the challenge, but don''t think you''ll be needing too much.  :D</td>', 'Great job on exposing the light correctly on this.  It''s a very cool find for this challenge.  I''d wish you good luck in the challenge, but don''t think you''ll be needing too much.  :D', '2006-11-10 14:11:44.000000', NULL, 1),
(3020305, 423652, 30049, '<td valign="top">Winning hand, winning photograph!  Great find, and a nice job on getting a properly exposed photograph of this sign.  Congrats!</td>', 'Winning hand, winning photograph!  Great find, and a nice job on getting a properly exposed photograph of this sign.  Congrats!', '2006-11-10 14:13:09.000000', NULL, 1),
(3020306, 424049, 30049, '<td valign="top">A refreshing composition.  Nicely done.  Sharp, well focused, and exposed correctly.  Good luck in the challenge.</td>', 'A refreshing composition.  Nicely done.  Sharp, well focused, and exposed correctly.  Good luck in the challenge.', '2006-11-10 14:14:07.000000', NULL, 1),
(3020310, 424026, 30049, '<td valign="top">Very nice job of properly capturing this photograph.  Clean, crisp...should do well.  Good luck.</td>', 'Very nice job of properly capturing this photograph.  Clean, crisp...should do well.  Good luck.', '2006-11-10 14:15:25.000000', NULL, 1),
(3020312, 424465, 30049, '<td valign="top">This is a wonderfully composed photo.  Ok, it''s centered, but how else could you do it?  :D  The lighting underneath, while not neon, certainly helps this image out tremendously.  Great eye to see this, and a well executed capture.  Good luck in the challenge.</td>', 'This is a wonderfully composed photo.  Ok, it''s centered, but how else could you do it?  :D  The lighting underneath, while not neon, certainly helps this image out tremendously.  Great eye to see this, and a well executed capture.  Good luck in the challenge.', '2006-11-10 14:17:20.000000', NULL, 1),
(3020313, 421631, 30049, '<td valign="top">Interesting perspective.  It''s unique and has an artistic flair to it.  Well done.  Good luck in the challenge.</td>', 'Interesting perspective.  It''s unique and has an artistic flair to it.  Well done.  Good luck in the challenge.', '2006-11-10 14:18:15.000000', NULL, 1),
(3020316, 424464, 30049, '<td valign="top">Nice angle getting this shot.  Hope you didn''t upset too many taxi''s while stepping off the curb to get it!  :D   The mist/fog with the lights on the roof adds another element that works well here.  Best of luck to you in the challenge.</td>', 'Nice angle getting this shot.  Hope you didn''t upset too many taxi''s while stepping off the curb to get it!  :D   The mist/fog with the lights on the roof adds another element that works well here.  Best of luck to you in the challenge.', '2006-11-10 14:19:56.000000', NULL, 1),
(3020363, 424043, 30049, '<td valign="top">Very cool time lapse exposure.  Hard to avoid a noisy sky with the longer shutter time.  Is that a crane way up there?  At first I thought it was a smear or something.  Connection to the Neon Signs challenge is a bit thin IMO.  Good luck.</td>', 'Very cool time lapse exposure.  Hard to avoid a noisy sky with the longer shutter time.  Is that a crane way up there?  At first I thought it was a smear or something.  Connection to the Neon Signs challenge is a bit thin IMO.  Good luck.', '2006-11-10 14:41:40.000000', NULL, 1),
(3020370, 423488, 30049, '<td valign="top">Uh-oh.  I wonder how many are going to slow down enough to find that teeny little neon sign in there?  Hmmm.  Good luck!</td>', 'Uh-oh.  I wonder how many are going to slow down enough to find that teeny little neon sign in there?  Hmmm.  Good luck!', '2006-11-10 14:43:03.000000', NULL, 1),
(3020374, 421558, 30049, '<td valign="top">It''s "ok".  Making the viewer work a bit too hard to find the neon signs IMO.  But hey, it''s certainly a unique approach to the challenge.  Good luck.</td>', 'It''s "ok".  Making the viewer work a bit too hard to find the neon signs IMO.  But hey, it''s certainly a unique approach to the challenge.  Good luck.', '2006-11-10 14:44:37.000000', NULL, 1),
(3020384, 423917, 30049, '<td valign="top">Very cool photograph.  Connection to the challenge theme is a bit thin IMO.  Technically, once you find it, the small ''Open'' neon sign qualifies it, but your image seems to be more about the bicyclist than a neon sign.  Good luck in the challenge.</td>', 'Very cool photograph.  Connection to the challenge theme is a bit thin IMO.  Technically, once you find it, the small ''Open'' neon sign qualifies it, but your image seems to be more about the bicyclist than a neon sign.  Good luck in the challenge.', '2006-11-10 14:46:58.000000', NULL, 1),
(3020398, 424157, 30049, '<td valign="top">Clean, clear, and well focused image.  Personally, I think for this challenge the neon gets lost here, especially going to a sepia tone rather than color.</td>', 'Clean, clear, and well focused image.  Personally, I think for this challenge the neon gets lost here, especially going to a sepia tone rather than color.', '2006-11-10 14:50:45.000000', NULL, 1),
(3020405, 424394, 30049, '<td valign="top">I like the way the light is reflected off the surrounding architecture.  Cute title.  :D</td>', 'I like the way the light is reflected off the surrounding architecture.  Cute title.  :D', '2006-11-10 14:51:41.000000', NULL, 1),
(3020413, 424332, 30049, '<td valign="top">Cool clock.  Unfortunately, this photo is a little bit too grainy and oversharpened to get maximum impact.  Good luck to you in the challenge.</td>', 'Cool clock.  Unfortunately, this photo is a little bit too grainy and oversharpened to get maximum impact.  Good luck to you in the challenge.', '2006-11-10 14:54:12.000000', NULL, 1),
(3020421, 424097, 30049, '<td valign="top">The wet reflections add a lot to this image.  Very good job on keeping the exposure under control.</td>', 'The wet reflections add a lot to this image.  Very good job on keeping the exposure under control.', '2006-11-10 14:56:04.000000', NULL, 1),
(3020436, 421824, 30049, '<td valign="top">Interesting perspective and unique approach to the challenge.  The border is really distracting (and why is the border not even - left side is thinner than the others?).  Other than that distraction, you have done a nice job with handling the exposure for the lighting quite well and brought out the details (even the fuzzy dust) also.  Good luck in the challenge.</td>', 'Interesting perspective and unique approach to the challenge.  The border is really distracting (and why is the border not even - left side is thinner than the others?).  Other than that distraction, you have done a nice job with handling the exposure for the lighting quite well and brought out the details (even the fuzzy dust) also.  Good luck in the challenge.', '2006-11-10 14:59:51.000000', NULL, 1),
(3020474, 424414, 30049, '<td valign="top">This is both interesting and unsettling at the same time.  Very good job of catching this reflection, however, in it''s current context it is kind of hard to tell it''s a neon sign.  Will be interesting to see where this one ends up.  Good luck.</td>', 'This is both interesting and unsettling at the same time.  Very good job of catching this reflection, however, in it''s current context it is kind of hard to tell it''s a neon sign.  Will be interesting to see where this one ends up.  Good luck.', '2006-11-10 15:19:55.000000', NULL, 1),
(3020475, 424215, 30049, '<td valign="top">Clever and unique entry for this challenge.  Looks like you may have pushed the reds a little too far in PP, but overall I think you''ve done a nice job with this entry.  Good luck.</td>', 'Clever and unique entry for this challenge.  Looks like you may have pushed the reds a little too far in PP, but overall I think you''ve done a nice job with this entry.  Good luck.', '2006-11-10 15:21:15.000000', NULL, 1),
(3020480, 423917, 42100, '<td valign="top">Neon is definitely at an absolute minimum in this photo, but quite obvious. So hopefully the DNMC nazis aren''t going to town on this very good photograph.</td>', 'Neon is definitely at an absolute minimum in this photo, but quite obvious. So hopefully the DNMC nazis aren''t going to town on this very good photograph.', '2006-11-10 15:23:25.000000', NULL, 1),
(3020547, 423291, 65603, '<td valign="top">The tail lights are a little distracting.</td>', 'The tail lights are a little distracting.', '2006-11-10 15:49:29.000000', NULL, 1),
(3020676, 424137, 66267, '<td valign="top">does not meet challenge</td>', 'does not meet challenge', '2006-11-10 16:49:49.000000', NULL, 1),
(3020684, 424414, 66267, '<td valign="top">Wow, if this is a real photograph its awseome. I dont know if its psp''s or not, but voting as if it were not.</td>', 'Wow, if this is a real photograph its awseome. I dont know if its psp''s or not, but voting as if it were not.', '2006-11-10 16:55:52.000000', NULL, 1),
(3020808, 424450, 50357, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2006-11-10 18:25:31.000000', NULL, 1),
