(3032686, 424405, 22734, '<td valign="top">Like an light island in the dark. Cool. Congratulations on your top 20 finish.</td>', 'Like an light island in the dark. Cool. Congratulations on your top 20 finish.', '2006-11-15 00:41:24.000000', NULL, 0),
(3032692, 424465, 22734, '<td valign="top">This is certainly impressive even at a glance. Very good capture. Congratulations on your top 20 finish.</td>', 'This is certainly impressive even at a glance. Very good capture. Congratulations on your top 20 finish.', '2006-11-15 00:42:20.000000', NULL, 0),
(3032695, 424182, 47541, '<td valign="top">Nice shot.  I think the angle put a lot off this - it would have me if I had voted.  If it had been level I think it would have made a great "L" shape with the pillars of neon at the left and then gradually falling away as you look along the roofline.  The rule of thirds at it''s best?<br/> <br/>I like to see some thinking to do something different so don''t be discouraged.</td>', 'Nice shot.  I think the angle put a lot off this - it would have me if I had voted.  If it had been level I think it would have made a great "L" shape with the pillars of neon at the left and then gradually falling away as you look along the roofline.  The rule of thirds at it''s best? I like to see some thinking to do something different so don''t be discouraged.', '2006-11-15 00:42:41.000000', NULL, 0),
(3032699, 423291, 22734, '<td valign="top">Neons and night motion. Very good! Congratulations on your top 20 finish.</td>', 'Neons and night motion. Very good! Congratulations on your top 20 finish.', '2006-11-15 00:43:00.000000', NULL, 0),
(3032712, 424098, 22734, '<td valign="top">Very well captured and presented. The neon blue plays well against the frosted glass. Congratulations on your top 20 finish.</td>', 'Very well captured and presented. The neon blue plays well against the frosted glass. Congratulations on your top 20 finish.', '2006-11-15 00:43:59.000000', NULL, 0),
(3032713, 424096, 1717, '<td valign="top">great shot, robert!   congrats on top 10 :)</td>', 'great shot, robert!   congrats on top 10 :)', '2006-11-15 00:44:09.000000', NULL, 0),
