(3032726, 422321, 22734, '<td valign="top">Congratulations on your top 20 finish. Great subject, colors  and movement feel.</td>', 'Congratulations on your top 20 finish. Great subject, colors  and movement feel.', '2006-11-15 00:45:35.000000', NULL, 0),
