(3032852, 421824, 27133, '<td valign="top">Wahooooooooooooooooooooooooooooo....my Tomboyb won...yayyyyyyyyyyyyyyyy!!<br/> <br/>Maybe I shouldn''t be writing this right thi minute...yayyyyyyyyyyyyyyyyyyyyyy!!</td>', 'Wahooooooooooooooooooooooooooooo....my Tomboyb won...yayyyyyyyyyyyyyyyy!! Maybe I shouldn''t be writing this right thi minute...yayyyyyyyyyyyyyyyyyyyyyy!!', '2006-11-15 01:05:51.000000', NULL, 0),
(3032881, 423728, 31399, '<td valign="top">wow..there IS a bulb out! cool touch.  you do the B/W conversion on this in ''channels'' or ''conversions''? take little selective color tweek and nix some black outta white and see if it helps image pop more? I like this...and with some Bradp or photoshoper geru''s input this might REALLY be even MORE of a winner.  I do KNOW it''s better than the score it received!</td>', 'wow..there IS a bulb out! cool touch.  you do the B/W conversion on this in ''channels'' or ''conversions''? take little selective color tweek and nix some black outta white and see if it helps image pop more? I like this...and with some Bradp or photoshoper geru''s input this might REALLY be even MORE of a winner.  I do KNOW it''s better than the score it received!', '2006-11-15 01:10:45.000000', NULL, 0),
(3032928, 424258, 57378, '<td valign="top">This was my only 10 - It was perfect - When a picture makes you wonder how it was takenand is also well executed - Then thats 10 in my book. Really well done. This would also make a great poster!<br/>Jeff<br/> <br/></td>', 'This was my only 10 - It was perfect - When a picture makes you wonder how it was takenand is also well executed - Then thats 10 in my book. Really well done. This would also make a great poster!Jeff ', '2006-11-15 01:24:45.000000', NULL, 0),
(3032953, 424414, 17148, '<td valign="top">I bet if you would have been validated faster it would have won the blue...but then I wouldn''t have my third yellow...so THANKS...great shot</td>', 'I bet if you would have been validated faster it would have won the blue...but then I wouldn''t have my third yellow...so THANKS...great shot', '2006-11-15 01:32:54.000000', NULL, 0),
(3032973, 424449, 65498, '<td valign="top">wow!!!! this is great !! Thank you all for your votes and comments. <br/>Times sq. had to have a great neon sign and I spent almost an hour until I found this one. The fact that it was rotating helped, as I shot it in several positions. But then, this one was a clear winner :)</td>', 'wow!!!! this is great !! Thank you all for your votes and comments. Times sq. had to have a great neon sign and I spent almost an hour until I found this one. The fact that it was rotating helped, as I shot it in several positions. But then, this one was a clear winner :)', '2006-11-15 01:39:41.000000', NULL, 0),
(3032974, 423991, 53316, '<td valign="top">Thanks for writing up those photographer''s comments - it was really neat to read.</td>', 'Thanks for writing up those photographer''s comments - it was really neat to read.', '2006-11-15 01:41:10.000000', NULL, 0),
(3032981, 423991, 17148, '<td valign="top">Love the feel to this shot. Looks like a vintage photo. It''s a great shot and has much more merit then alot of people gave it credit for. Well done</td>', 'Love the feel to this shot. Looks like a vintage photo. It''s a great shot and has much more merit then alot of people gave it credit for. Well done', '2006-11-15 01:47:04.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3032998, 423991, 20462, '<td valign="top">Yeah, i thought of Colfax for about 2 seconds and said nah, that''s bleepin'' nuts.  People, this is not a a safe area and honestly not a safe place to be at night.  But, good job for tryin''.  And being brave.</td>', 'Yeah, i thought of Colfax for about 2 seconds and said nah, that''s bleepin'' nuts.  People, this is not a a safe area and honestly not a safe place to be at night.  But, good job for tryin''.  And being brave.', '2006-11-15 01:57:37.000000', NULL, 0),
(3033014, 423312, 66923, '<td valign="top">I can not believe this scored sooo low!! dunno whats wrong with some ppl over here. What do u mean??? If its not colour its not neon? its not ok to have BW? WHY??? Why do you all want colour? U act like a 10 year old girl... come on, ppl, u call yourselves photographers, but u can not appreciate a good shot. Oh, my..u gotta have colours, poor babies... sorry for the tone, y''all, but i just can''t believe how u score around here, not just with this challenge... Good luck to you all...</td>', 'I can not believe this scored sooo low!! dunno whats wrong with some ppl over here. What do u mean??? If its not colour its not neon? its not ok to have BW? WHY??? Why do you all want colour? U act like a 10 year old girl... come on, ppl, u call yourselves photographers, but u can not appreciate a good shot. Oh, my..u gotta have colours, poor babies... sorry for the tone, y''all, but i just can''t believe how u score around here, not just with this challenge... Good luck to you all...', '2006-11-15 02:07:00.000000', NULL, 0),
(3033019, 424485, 66923, '<td valign="top">gave this a ten, its a great shot. cant believe ppl are so shallow to score this one low just because it is not colour. Its a great composition, u ppl are killing me with the colours... some of u round here must abdolutely LOOOVE the challanges with little silly flowers and bloody tacky sunsets...</td>', 'gave this a ten, its a great shot. cant believe ppl are so shallow to score this one low just because it is not colour. Its a great composition, u ppl are killing me with the colours... some of u round here must abdolutely LOOOVE the challanges with little silly flowers and bloody tacky sunsets...', '2006-11-15 02:10:47.000000', NULL, 0),
(3033024, 424258, 57260, '<td valign="top">Way to go Sean. Brilliant and well done. Congratulations</td>', 'Way to go Sean. Brilliant and well done. Congratulations', '2006-11-15 02:15:40.000000', NULL, 0),
(3033030, 424027, 41337, '<td valign="top">Dude! Congrats! Las Vegas is one heck of a place to be for a neon challenge.</td>', 'Dude! Congrats! Las Vegas is one heck of a place to be for a neon challenge.', '2006-11-15 02:23:13.000000', NULL, 0),
